import java.util.Scanner;

public class Main {
    static int n, m, md;
    static int[][] c = new int[505][505];
    static int[][] dpf = new int[505][505];
    static int[][] dpr = new int[505][505];
    static long[] f = new long[505];
    static long[] rst = new long[505];

    static long sum(long x) {
        return (x * (x + 1L)) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        md = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            c[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % md;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= i; k++) {
                long current = c[i][k];
                long crst = 0;
                if (k > 0) {
                    crst = (crst * f[k - 1] + current * rst[k - 1]) % md;
                    current = (current * f[k - 1]) % md;
                }
                if (k < i) {
                    crst = (crst * f[i - k - 1] + current * rst[i - k - 1]) % md;
                    current = (current * f[i - k - 1]) % md;
                }
                rst[i] = (rst[i] + crst * (i + 2) + current * (sum(k) + sum(i - k))) % md;
                f[i] = (f[i] + (i + 2) * current) % md;
            }
        }

        dpf[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i && j <= m; j++) {
                dpf[i][j] = dpf[i - 1][j];
                dpr[i][j] = dpr[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    int prev = i - k;
                    if (prev > 0) prev--;
                    if (j - k <= prev) {
                        long temp1 = (dpr[prev][j - k] * f[k - 1] + dpf[prev][j - k] * rst[k - 1]) % md;
                        long temp2 = (dpf[prev][j - k] * f[k - 1]) % md;
                        dpr[i][j] = (int)((dpr[i][j] + c[j][k] * temp1) % md);
                        dpf[i][j] = (int)((dpf[i][j] + c[j][k] * temp2) % md);
                    }
                }
            }
        }

        System.out.println(dpr[n][m]);
        sc.close();
    }
}

